const db = require('better-sqlite3')('/workspace/world.db');

const subject = 'Re: High Priority: Onboarding Equipment Setup Needed - Confirmation';
const fromAddr = 'priya.it.lead@company.com';
const toAddr = 'ethan.it.specialist@company.com';
const content = \`Hello Ethan,

I wanted to confirm that the onboarding equipment setup for the new contractor is being tracked and has been scheduled on our calendar for September 4, 2026.

Please ensure the following items are ready before start of business on September 5, 2026:

1. Standard Windows laptop — provisioned and configured
2. VPN access — set up and tested
3. Email account — created and accessible

This is a high-priority request from Olivia (HR). Let me know if you run into any blockers or need additional resources to meet the deadline.

Best regards,
Priya\`;

const insertStmt = db.prepare(\`
  INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`);

// Insert into Ethan's inbox
insertStmt.run(
  'ethan.it.specialist/' + subject + '.eml',
  'ethan.it.specialist',
  fromAddr,
  toAddr,
  subject,
  content,
  'ethan.it.specialist'
);

// Insert into Priya's sent/inbox
insertStmt.run(
  'priya.it.lead/' + subject + '.eml',
  'priya.it.lead',
  fromAddr,
  toAddr,
  subject,
  content,
  'priya.it.lead'
);

// Verify
const sent = db.prepare(\"SELECT * FROM ob_emails WHERE subject = ?\").all(subject);
for (const e of sent) {
  console.log(JSON.stringify(e, null, 2));
  console.log('---');
}
"
